B.b6Z=s(["Quiero a mi mam\xe1.","T\xf4i y\xeau m\u1eb9."],t.s)
B.afe=s(["\xa1Hola, maestra!","Em ch\xe0o c\xf4 \u1ea1!"],t.s)
